/* @lc app=leetcode id=1976 lang=kotlin */
class Solution { fun countPaths(n: Int, roads: Array<IntArray>): Int = Array(n) { mutableListOf<Pair<Int, Long>>() }.apply { roads.forEach { r -> this[r[0]].add(r[1] to r[2].toLong()).also { this[r[1]].add(r[0] to r[2].toLong()) } } }.let { adj -> LongArray(n) { Long.MAX_VALUE }.also { it[0] = 0L }.let { dist -> LongArray(n).also { it[0] = 1L }.let { ways -> java.util.PriorityQueue<Pair<Int, Long>>(compareBy { it.second }).apply { add(0 to 0L) }.let { pq -> generateSequence { if (pq.isNotEmpty()) pq.poll() else null }.forEach { (u, d) -> if (d <= dist[u]) adj[u].forEach { (v, w) -> (d + w).let { nextD -> if (nextD < dist[v]) dist[v] = nextD.also { ways[v] = ways[u] }.also { pq.add(v to nextD) } else if (nextD == dist[v]) ways[v] = (ways[v] + ways[u]) % 1000000007L } } }.run { ways[n - 1].toInt() } } } } }